{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None), event("b", 1, False)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_and_handles_empty_groups():
    groups = {"small": [event("a", 1, True)],
              "large": [event(str(i), 1, False) for i in range(3)],
              "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_boundaries():
    assert flags_in_window([2, 0, 3], 0) == 0
    assert flags_in_window([2, 0, 3], 1) == 3
    assert flags_in_window([2, 0, 3], 2) == 3
    assert flags_in_window([2, 0, 3], 10) == 5
    assert flags_in_window([], 2) == 0


def test_parse_fields_and_skipped_lines():
    lines = ["\n", "  # a comment", " \t ", " a , 1 , 1 ",
             "b, -2, 0", "c, 3,  "]
    assert parse_transcript_log(lines) == [event("a", 1, True),
                                            event("b", -2, False),
                                            event("c", 3, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1,yes"])
def test_parse_error_reports_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", " # comment", "a,1,1", bad_line])


def test_dedupe_duplicate_ids_keep_last_and_sort_by_day_then_id():
    events = [event("b", 0, True), event("a", 2, True),
              event("b", 2, False), event("c", 1, None),
              event("a", 2, None)]
    assert dedupe_transcripts(events) == [events[3], events[4], events[2]]
    assert dedupe_transcripts([]) == []


def test_daily_counts_include_gaps_and_filter_range():
    events = [event("a", 0, True), event("b", 1, True),
              event("c", 1, True), event("d", 2, None),
              event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": [event("a", 1, True), event("b", 1, False),
                    event("c", 4, True)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 1}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary(groups, 20)["recent"] == 2
    assert monitor_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [],
              "a": [event("a", 1, True)], "b": [event("b", 1, False)]}
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []


def test_rates_by_group_include_empty_in_sorted_order():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_streak_resets_on_zero_and_negative_counts():
    assert longest_flag_streak([1, 2, 0, 1, -1, 1, 1, 1]) == 3
    assert longest_flag_streak([0, -1]) == 0
    assert longest_flag_streak([]) == 0
